<?php $c=$campaign??[];$editing=!empty($c); ?><form action="<?= base_url($editing?'campaigns/'.$c['id'].'/update':'campaigns/create') ?>" method="post" class="mt-7 grid gap-5 xl:grid-cols-[1fr_1.4fr]"><?= csrf_field() ?><section class="card space-y-4 p-6"><h2 class="text-lg font-extrabold">Campaign details</h2><label class="block text-xs font-bold">Internal name<input name="name" required value="<?= esc(old('name',$c['name']??'')) ?>" class="field mt-2"></label><label class="block text-xs font-bold">Subject<input name="subject" required value="<?= esc(old('subject',$c['subject']??'')) ?>" class="field mt-2"></label><label class="block text-xs font-bold">Preview text<input name="preview_text" value="<?= esc(old('preview_text',$c['preview_text']??'')) ?>" class="field mt-2"></label><div class="grid grid-cols-2 gap-3"><label class="text-xs font-bold">From name<input name="from_name" required value="<?= esc(old('from_name',$c['from_name']??'Brightside')) ?>" class="field mt-2"></label><label class="text-xs font-bold">From email<input name="from_email" type="email" required value="<?= esc(old('from_email',$c['from_email']??'hello@example.com')) ?>" class="field mt-2"></label></div><label class="block text-xs font-bold">Schedule later (leave empty for draft)<input name="scheduled_at" type="datetime-local" value="<?= !empty($c['scheduled_at'])?date('Y-m-d\TH:i',strtotime($c['scheduled_at'])):'' ?>" class="field mt-2"></label><label class="block text-xs font-bold">Timezone<select name="timezone" class="field mt-2"><option>Asia/Kolkata</option><option>UTC</option><option>America/New_York</option><option>Europe/London</option></select></label></section><section class="card p-6"><div class="flex items-center justify-between"><h2 class="text-lg font-extrabold">Email editor</h2><select name="editor_type" class="field max-w-40"><option value="richtext">Rich text</option><option value="html">HTML</option><option value="dragdrop">Drag & drop</option></select></div><textarea name="content_html" rows="18" class="field mt-5 font-mono text-sm" placeholder="Build your email with HTML or rich text…"><?= esc(old('content_html',$c['content_html']??'<h1>Hello {{first_name}}</h1>\n<p>Share your story here.</p>')) ?></textarea><div class="mt-5 flex flex-wrap justify-end gap-3"><?php if($editing): ?><button formaction="<?= base_url('campaigns/'.$c['id'].'/test') ?>" class="btn shadow-soft">Send test</button><?php endif ?><button type="button" onclick="previewEmail()" class="btn shadow-soft">Preview</button><button class="btn btn-primary">Save campaign</button></div></section></form><dialog id="preview" class="h-[80vh] w-full max-w-2xl rounded-3xl bg-white p-6 backdrop:bg-[#153b39]/30"><button onclick="this.closest('dialog').close()" class="float-right"><i data-lucide="x"></i></button><div id="previewBody" class="prose mt-10"></div></dialog><script>function previewEmail(){document.getElementById('previewBody').innerHTML=document.querySelector('[name=content_html]').value;document.getElementById('preview').showModal()}</script>
